/**
 * Genera un mapa de montañas equilibrado con vegetación orgánica y masas de agua claras.
 */
function buildNaturalMountains(originX = 0, originY = 0, originZ = 0, options = {}) {  
    const mapWidth = options.mapWidth || 512;
    const mapHeight = options.mapHeight || 40;
    const mapDepth = options.mapDepth || 512;

    const seaLevel = 7;
    const snowLine = 30; // Subimos la cota de nieve para no saturalo de piedra/blanco

    if (typeof beginBatch === 'function') beginBatch();

    // Ruido más suave para evitar pendientes hiperagresivas que generen demasiada roca
    function getHeight(x, z) {
        const fx = x * 0.035;
        const fz = z * 0.035;

        const baseVal = Math.sin(fx) * Math.cos(fz);
        const detailVal = Math.sin(fx * 2.1 + fz * 1.8) * 0.35;

        const combined = (baseVal + detailVal + 1.35) / 2.7;
        return Math.floor(4 + combined * (mapHeight - 8));
    }

    for (let x = 0; x < mapWidth; x++) {
        for (let z = 0; z < mapDepth; z++) {
            const surfaceY = getHeight(x, z);

            const hRight = getHeight(Math.min(x + 1, mapWidth - 1), z);
            const hForward = getHeight(x, Math.min(z + 1, mapDepth - 1));
            const slope = Math.abs(surfaceY - hRight) + Math.abs(surfaceY - hForward);

            // 1. ESTRUCTURA Y CAPAS DEL TERRENO
            for (let y = 0; y <= Math.max(surfaceY, seaLevel); y++) {
                const gx = originX + x;
                const gy = originY + y;
                const gz = originZ + z;

                if (y > surfaceY && y <= seaLevel) {
                    // Cuerpos de agua (usamos 'ice' para simular la masa de agua limpia)
                    setVoxel(gx, gy, gz, options.waterMat || 'ice');
                } else if (y <= surfaceY) {
                    let mat = 'stone';

                    if (y === surfaceY) {
                        if (y <= seaLevel + 1) {
                            mat = 'sand'; // Playas
                        } else if (slope >= 4) { // Subimos el umbral de pendiente para no mostrar tanta piedra
                            mat = 'stone';
                        } else if (y >= snowLine) {
                            mat = 'white_wool'; // Nieve en picos altos
                        } else {
                            mat = 'grass';
                        }
                    } else if (y >= surfaceY - 3) {
                        mat = (surfaceY <= seaLevel + 1) ? 'sand' : 'dirt'; // sand o sandstone?
                    } else {
                        mat = (y === 0) ? 'obsidian' : 'stone';
                    }

                    setVoxel(gx, gy, gz, mat);
                }
            }

            // 2. VEGETACIÓN Y DETALLES
            const isGrass = surfaceY > seaLevel + 1 && surfaceY < snowLine && slope < 4;
            if (isGrass) {
                const rng = Math.abs(Math.sin(x * 12.9898 + z * 78.233)) * 43758.5453;
                const val = rng - Math.floor(rng);

                const topY = originY + surfaceY + 1;

                // Árboles con hojas verdes reales 
                if (val < 0.012 && x >= 3 && x < mapWidth - 3 && z >= 3 && z < mapDepth - 3) {
                    const trunkH = 4 + (Math.floor(val * 100) % 2);
                    const leafMat = options.leafMat || 'green_concrete'; // Hojas en verde orgánico

                    // Tronco de madera
                    for (let th = 0; th < trunkH; th++) {
                        setVoxel(originX + x, topY + th, originZ + z, options.trunkMat || 'log');
                    }

                    // Copa de hojas
                    const leafBase = topY + trunkH - 2;
                    for (let lx = -2; lx <= 2; lx++) {
                        for (let lz = -2; lz <= 2; lz++) {
                            for (let ly = 0; ly <= 2; ly++) {
                                // Esquinas redondeadas
                                if (Math.abs(lx) === 2 && Math.abs(lz) === 2 && ly >= 1) continue;
                                if (lx === 0 && lz === 0 && ly < 2) continue;

                                // Las hojas van por TERRENO: la máscara de `caras` y el `atravesable` del
                                // documento ya llegan a mc.grid, así que un bosque entero cuesta CERO draw
                                // calls extra. game.stamp sería una estructura (y un draw call) por hoja.
                                setVoxel(originX + x + lx, leafBase + ly, originZ + z + lz, leafMat);
                            }
                        }
                    }
                } 
                // Plantas/Flores pequeñas dispersas (evita el look vacío)
                else if (val > 0.94) {
                    setVoxel(originX + x, topY, originZ + z, options.yellowFlower);
                    //game.stamp(options.yellowFlower, originX + x, topY, originZ + z);
                } else if (val > 0.91) {
                    setVoxel(originX + x, topY, originZ + z, options.redFlower);
                    //game.stamp(options.redFlower, originX + x, topY, originZ + z);
                }
            }
        }
    }

    if (typeof endBatch === 'function') endBatch();
}
